#include <Arduino.h>
#include <WiFi.h>
#include <Preferences.h>
#include <SPI.h>
#include <TFT_eSPI.h>
#include <RadioLib.h>
#include <RotaryEncoder.h>

// LILYGO T-Embed CC1101 V1.0 pinout
static constexpr int PIN_PWR_EN = 15;
static constexpr int PIN_SW1 = 47;
static constexpr int PIN_SW0 = 48;
static constexpr int PIN_CC_CS = 12;
static constexpr int PIN_CC_GDO0 = 3;
static constexpr int PIN_CC_GDO2 = 38;
static constexpr int PIN_ENC_A = 4;
static constexpr int PIN_ENC_B = 5;
static constexpr int PIN_ENC_KEY = 0;
static constexpr float WMBUS_FREQ_MHZ = 868.95f;

TFT_eSPI tft;
Preferences prefs;
RotaryEncoder encoder(PIN_ENC_A, PIN_ENC_B, RotaryEncoder::LatchMode::TWO03);
CC1101 radio = new Module(PIN_CC_CS, PIN_CC_GDO0, RADIOLIB_NC, PIN_CC_GDO2, SPI);

enum Screen { HOME, WIFI_MENU, WIFI_LIST, WIFI_PASSWORD, WIFI_STATUS, RADIO_INFO };
Screen screen = HOME;

String savedSsid, savedPass;
String networks[24];
int networkCount = 0;
int selected = 0;
String passwordInput;
String keyboard = " abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+.";
int keyIndex = 0;
bool radioReady = false;
bool wifiConnecting = false;
unsigned long lastDraw = 0;
long lastEncoder = 0;
volatile bool packetFlag = false;

void IRAM_ATTR onPacket() { packetFlag = true; }

void drawHeader(const char* title) {
  tft.fillScreen(TFT_BLACK);
  tft.setTextColor(TFT_CYAN, TFT_BLACK);
  tft.setTextSize(2);
  tft.setCursor(6, 5);
  tft.println(title);
  tft.drawFastHLine(5, 30, 310, TFT_DARKGREY);
  tft.setTextSize(1);
  tft.setTextColor(TFT_WHITE, TFT_BLACK);
}

void drawLine(int y, const String& s, bool active=false) {
  if (active) {
    tft.fillRoundRect(5, y-2, 310, 22, 4, TFT_DARKCYAN);
    tft.setTextColor(TFT_WHITE, TFT_DARKCYAN);
  } else {
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
  }
  tft.setCursor(10, y+3);
  tft.setTextSize(2);
  tft.print(s);
}

void drawHome() {
  drawHeader("W-MBus Reader");
  drawLine(42, "Skanuj / odbior", selected==0);
  drawLine(68, "Ustawienia Wi-Fi", selected==1);
  drawLine(94, "Status Wi-Fi", selected==2);
  drawLine(120, "Radio CC1101", selected==3);
  tft.setTextSize(1);
  tft.setTextColor(TFT_YELLOW, TFT_BLACK);
  tft.setCursor(8, 154);
  tft.printf("868.95 MHz | CC1101: %s", radioReady ? "OK" : "BLAD");
  tft.setCursor(8, 166);
  tft.printf("Wi-Fi: %s", WiFi.isConnected() ? WiFi.localIP().toString().c_str() : "offline");
}

void drawWifiMenu() {
  drawHeader("Ustawienia Wi-Fi");
  drawLine(45, "Skanuj sieci", selected==0);
  drawLine(73, "Polacz zapisane", selected==1);
  drawLine(101, "Usun konfiguracje", selected==2);
  drawLine(129, "Powrot", selected==3);
  tft.setTextSize(1);
  tft.setCursor(8, 158);
  tft.print(savedSsid.length() ? "Zapisana siec: " + savedSsid : "Brak zapisanej sieci");
}

void drawNetworkList() {
  drawHeader("Wybierz siec");
  for (int i=0; i<min(networkCount, 5); i++) {
    int idx = (selected/5)*5+i;
    if (idx >= networkCount) break;
    drawLine(40+i*25, networks[idx], idx==selected);
  }
  tft.setTextSize(1);
  tft.setCursor(8, 164);
  tft.printf("%d/%d  Kliknij: wybor | przytrzymaj: powrot", selected+1, networkCount);
}

void drawPassword() {
  drawHeader("Haslo Wi-Fi");
  tft.setTextSize(2);
  tft.setCursor(8, 43);
  tft.print(passwordInput + "_");
  tft.setTextSize(1);
  tft.setCursor(8, 76);
  tft.printf("Znak: [%c]  Pokretlo: zmiana", keyboard[keyIndex]);
  tft.setCursor(8, 94);
  tft.print("Klik: dodaj znak");
  tft.setCursor(8, 112);
  tft.print("Przytrzymaj: zatwierdz");
  tft.setCursor(8, 140);
  tft.print("Specjalny znak: spacja na poczatku");
}

void drawWifiStatus() {
  drawHeader("Status Wi-Fi");
  tft.setTextSize(2);
  tft.setCursor(8, 48);
  tft.println(WiFi.isConnected() ? "POLACZONO" : "BRAK POLACZENIA");
  tft.setTextSize(1);
  tft.setCursor(8, 85);
  tft.println("SSID: " + WiFi.SSID());
  tft.setCursor(8, 102);
  tft.println("IP: " + (WiFi.isConnected() ? WiFi.localIP().toString() : String("-")));
  tft.setCursor(8, 130);
  tft.println("Kliknij, aby wrocic");
}

void drawRadioInfo() {
  drawHeader("CC1101");
  tft.setTextSize(2);
  tft.setCursor(8, 48);
  tft.printf("Radio: %s", radioReady ? "OK" : "BLAD");
  tft.setTextSize(1);
  tft.setCursor(8, 82);
  tft.println("Czestotliwosc: 868.95 MHz");
  tft.setCursor(8, 100);
  tft.println("Odbior telegramow: prototyp");
  tft.setCursor(8, 118);
  tft.println("Dekoder W-MBus: jeszcze nie");
  tft.setCursor(8, 145);
  tft.println("Kliknij, aby wrocic");
}

void render() {
  switch(screen) {
    case HOME: drawHome(); break;
    case WIFI_MENU: drawWifiMenu(); break;
    case WIFI_LIST: drawNetworkList(); break;
    case WIFI_PASSWORD: drawPassword(); break;
    case WIFI_STATUS: drawWifiStatus(); break;
    case RADIO_INFO: drawRadioInfo(); break;
  }
}

bool connectWifi(const String& ssid, const String& pass, uint32_t timeoutMs=15000) {
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid.c_str(), pass.c_str());
  unsigned long start = millis();
  while (millis()-start < timeoutMs) {
    if (WiFi.status() == WL_CONNECTED) return true;
    delay(100);
  }
  return false;
}

void saveWifi(const String& ssid, const String& pass) {
  prefs.begin("wmbus", false);
  prefs.putString("ssid", ssid);
  prefs.putString("pass", pass);
  prefs.end();
  savedSsid = ssid;
  savedPass = pass;
}

void scanWifi() {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(true, true);
  delay(200);
  int n = WiFi.scanNetworks(false, true);
  networkCount = 0;
  for (int i=0; i<n && networkCount<24; i++) {
    if (WiFi.SSID(i).length()) networks[networkCount++] = WiFi.SSID(i);
  }
  WiFi.scanDelete();
  selected = 0;
  screen = WIFI_LIST;
}

bool buttonPressed() {
  static bool prev = true;
  static unsigned long downAt = 0;
  bool now = digitalRead(PIN_ENC_KEY);
  if (prev && !now) downAt = millis();
  bool click = !prev && now && millis()-downAt > 30 && millis()-downAt < 700;
  prev = now;
  return click;
}
bool buttonLongPressed() {
  static bool fired = false;
  static unsigned long downAt = 0;
  bool now = digitalRead(PIN_ENC_KEY)==LOW;
  if (now && !fired) { downAt=millis(); fired=true; }
  if (!now && fired) { bool result=millis()-downAt>=700; fired=false; return result; }
  return false;
}

void handleEncoder() {
  encoder.tick();
  long p = encoder.getPosition();
  if (p != lastEncoder) {
    int delta = (int)(p-lastEncoder);
    lastEncoder = p;
    if (screen == WIFI_PASSWORD) {
      keyIndex = (keyIndex + delta + keyboard.length()) % keyboard.length();
    } else if (screen == WIFI_LIST) {
      selected = constrain(selected + delta, 0, max(0, networkCount-1));
    } else {
      int maxItem = screen==HOME ? 3 : 3;
      selected = constrain(selected + delta, 0, maxItem);
    }
    render();
  }

  if (buttonLongPressed()) {
    if (screen == WIFI_PASSWORD) {
      saveWifi(networks[selected], passwordInput);
      tft.fillScreen(TFT_BLACK);
      tft.setCursor(8,50); tft.setTextColor(TFT_WHITE); tft.setTextSize(2);
      tft.println("Laczenie...");
      bool ok=connectWifi(savedSsid,savedPass);
      if(ok) saveWifi(savedSsid,savedPass);
      screen=WIFI_STATUS;
    } else if (screen == WIFI_LIST || screen==WIFI_MENU || screen==RADIO_INFO || screen==WIFI_STATUS) {
      screen = (screen==WIFI_LIST) ? WIFI_MENU : HOME;
      selected=0;
    }
    render();
    return;
  }

  if (buttonPressed()) {
    if (screen==HOME) {
      if(selected==0) screen=RADIO_INFO;
      if(selected==1) { screen=WIFI_MENU; selected=0; }
      if(selected==2) screen=WIFI_STATUS;
      if(selected==3) screen=RADIO_INFO;
    } else if (screen==WIFI_MENU) {
      if(selected==0) scanWifi();
      else if(selected==1) {
        if(savedSsid.length()) connectWifi(savedSsid,savedPass);
        screen=WIFI_STATUS;
      } else if(selected==2) {
        prefs.begin("wmbus",false); prefs.clear(); prefs.end();
        savedSsid=""; savedPass=""; WiFi.disconnect(true,true);
      } else { screen=HOME; selected=0; }
    } else if (screen==WIFI_LIST) {
      if(networkCount) { passwordInput=""; keyIndex=0; screen=WIFI_PASSWORD; }
    } else if (screen==WIFI_PASSWORD) {
      char c=keyboard[keyIndex];
      if(c==' ') { if(passwordInput.length()) passwordInput.remove(passwordInput.length()-1); }
      else if(passwordInput.length()<63) passwordInput+=c;
    } else {
      screen=HOME; selected=0;
    }
    render();
  }
}

void setupRadio() {
  // Band switch: SW1 LOW, SW0 HIGH for 868/915 MHz.
  pinMode(PIN_SW1, OUTPUT); digitalWrite(PIN_SW1, LOW);
  pinMode(PIN_SW0, OUTPUT); digitalWrite(PIN_SW0, HIGH);
  SPI.begin(11,10,9,PIN_CC_CS);
  int16_t state = radio.begin(WMBUS_FREQ_MHZ, 100.0, 50.0, 203.0, 10, 16);
  radioReady = (state == RADIOLIB_ERR_NONE);
  if (radioReady) {
    radio.setPacketReceivedAction(onPacket);
    radio.startReceive();
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_PWR_EN, OUTPUT); digitalWrite(PIN_PWR_EN, HIGH);
  pinMode(PIN_ENC_KEY, INPUT_PULLUP);
  pinMode(PIN_ENC_A, INPUT_PULLUP);
  pinMode(PIN_ENC_B, INPUT_PULLUP);
  tft.init();
  tft.setRotation(1);
  tft.fillScreen(TFT_BLACK);
  prefs.begin("wmbus", true);
  savedSsid=prefs.getString("ssid","");
  savedPass=prefs.getString("pass","");
  prefs.end();
  setupRadio();
  if(savedSsid.length()) {
    WiFi.mode(WIFI_STA);
    WiFi.begin(savedSsid.c_str(),savedPass.c_str());
  }
  render();
}

void loop() {
  handleEncoder();
  if(packetFlag) {
    packetFlag=false;
    // This is only a radio packet event. It is NOT yet a valid Wireless M-Bus decoder.
    uint8_t buf[256];
    size_t len=radio.getPacketLength();
    if(len>0 && len<=sizeof(buf)) {
      int16_t err=radio.readData(buf,len);
      if(err==RADIOLIB_ERR_NONE) {
        Serial.printf("CC1101 packet len=%u RSSI=%.1f dBm HEX=", (unsigned)len, radio.getRSSI());
        for(size_t i=0;i<len;i++) Serial.printf("%02X",buf[i]);
        Serial.println();
      }
    }
    radio.startReceive();
  }
  if(millis()-lastDraw>3000) {
    lastDraw=millis();
    if(screen==HOME) render();
  }
}
